This class wraps handle native spatial reference.
Whenever you got an AO spatial reference handle from interop layer
immediately wrap it in this class so that handle is automatically released, and no memory is leaked.
using (var srHandle = SpatialReferenceHandle.CreateFromAOHandle(aoSRHandle))
{
   do something here, usually passing the srHandle.GetIntPtr() to interop layer
   Note that srHandle.GetIntPtr() will equal to aoSRHandle
   so either can be used.
}//it will be release here
Also the SpatialReferenceHandle can be created from .Net SpatialReference object
It will use caching to reuse native spatial reference objects.
using (var srHandle = SpatialReferenceHandle.Create(spatialReference))
{
   do something here, usually passing the srHandle.GetIntPtr() to interop layer
}//it will be release here

This class wraps AO handle of native VerticalCoordinateSystem.
The handle should be used each time when an AO handle is returned from Interop methods.
It allows to release AO handle safely and in time.
Typically it is used in conjunction with the using statement.
using (var vcsHandle = VCSHandle.CreateFromAOHandle(aoVCSHandle))
{
   do something here, usually passing the vcsHandle.GetIntPtr() to interop layer
   Note that vcsHandle.GetIntPtr() will equal to aoVCSHandle
   so either can be used.
}//it will be release here
Also the VCSHandleHandle can be created from .Net VerticalCoordinateSystem object
It will use caching to reuse native vcs objects.
using (var vcsHandle = VCSHandle.Create(vcs))
{
   do something here, usually passing the vcsHandle.GetIntPtr() to interop layer
}//it will be release here

example.code:
//Consult https://github.com/Esri/arcade-expressions/ and
//https://developers.arcgis.com/arcade/ for more examples
//and arcade reference

QueuedTask.Run(() =>
{
  //construct an expression
  var query = @"Count($layer)";//count of features in "layer"

  //construct a CIMExpressionInfo
  var arcade_expr = new CIMExpressionInfo()
  {
    Expression = query.ToString(),
    //Return type can be string, numeric, or default
    //When set to default, addin is responsible for determining
    //the return type
    ReturnType = ExpressionReturnType.Default
  };

  //Construct an evaluator
  //select the relevant profile - it must support Pro and it must
  //contain any profile variables you are using in your expression.
  //Consult: https://developers.arcgis.com/arcade/profiles/
  using (var arcade = ArcadeScriptEngine.Instance.CreateEvaluator(
                          arcade_expr, ArcadeProfile.Popups))
  {
    //Provision  values for any profile variables referenced...
    //in our case '$layer'
    var variables = new List<KeyValuePair<string, object>>() {
              new KeyValuePair<string, object>("$layer", featLayer)
      };
    //evaluate the expression
    try
    {
      var result = arcade.Evaluate(variables).GetResult();
      System.Diagnostics.Debug.WriteLine($"Result: {result.ToString()}");
    }
    //handle any exceptions
    catch (InvalidProfileVariableException ipe)
    {
      //something wrong with the profile variable specified
      //TODO...
    }
    catch (EvaluationException ee)
    {
      //something wrong with the query evaluation
      //TODO...
    }

  }
});

//Consult https://github.com/Esri/arcade-expressions/ and
//https://developers.arcgis.com/arcade/ for more examples
//and arcade reference

QueuedTask.Run(() =>
{
  //construct an expression
  var query = @"$feature.AreaInAcres * 43560.0";//convert acres to ft 2

  //construct a CIMExpressionInfo
  var arcade_expr = new CIMExpressionInfo()
  {
    Expression = query.ToString(),
    //Return type can be string, numeric, or default
    //When set to default, addin is responsible for determining
    //the return type
    ReturnType = ExpressionReturnType.Default
  };

  //Construct an evaluator
  //select the relevant profile - it must support Pro and it must
  //contain any profile variables you are using in your expression.
  //Consult: https://developers.arcgis.com/arcade/profiles/
  using (var arcade = ArcadeScriptEngine.Instance.CreateEvaluator(
                          arcade_expr, ArcadeProfile.Popups))
  {
    //we are evaluating the expression against all features
    using (var rc = featLayer.Search())
    {

      while (rc.MoveNext())
      {
        //Provision  values for any profile variables referenced...
        //in our case '$feature'
        var variables = new List<KeyValuePair<string, object>>() {
                new KeyValuePair<string, object>("$feature", rc.Current)
        };
        //evaluate the expression (per feature in this case)
        try
        {
          var result = arcade.Evaluate(variables).GetResult();
          var val = ((double)result).ToString("0.0#");
          System.Diagnostics.Debug.WriteLine(
            $"{rc.Current.GetObjectID()} area: {val} ft2");
        }
        //handle any exceptions
        catch (InvalidProfileVariableException ipe)
        {
          //something wrong with the profile variable specified
          //TODO...
        }
        catch (EvaluationException ee)
        {
          //something wrong with the query evaluation
          //TODO...
        }
      }
    }
  }
});

