  ////      while (rc.MoveNext())
  ////      {
  ////        var variables = new List<KeyValuePair<string, object>>() {
  ////          new KeyValuePair<string, object>("$feature", rc.Current)
  ////        };

  ////        var result = arcade.Evaluate(variables).GetResult();
  ////        //output
  ////        //...
  ////      }
  ////    }
  ////  }
  ////}
});

