FilterType = KGFilterType.Include,//default
NamedType = "R1"
};
var kg_filter1_r2 = new CIMKnowledgeGraphNamedTypeFilterByType()
{
FilterType = KGFilterType.Include,//default
NamedType = "R2"
};

