  theLabelClass.MaplexLabelPlacementProperties.PolygonPlacementMethod =
                      MaplexPolygonPlacementMethod.HorizontalInPolygon;
  theLabelClass.MaplexLabelPlacementProperties.CanPlaceLabelOutsidePolygon = true;
}

