  {
    WhereClause = "name = 'Acme'",
    SubFields = "*"
  };
  using (var rc = org_fl.Search(qf))
  {
    if (!rc.MoveNext())
      return;
    org_oid = rc.Current.GetObjectID();
    org_gid = rc.Current.GetGlobalID();
