  var kg_prop_info = kg.GetPropertyNameInfo();
  var sql = $"{kg_prop_info.OriginIDPropertyName} = ";
  sql += "'" + org_gid.ToString("B").ToUpper() + "'";

  qf = new QueryFilter()
  {
    WhereClause = sql,
    SubFields = "*"
